// One ESP32 message -> rows for the SAME 'machine' table the Factory Monitoring dashboard reads.
// The ESP32 sends running totals (seconds in each state). We write only what changed.
const p  = msg.payload;                        // parsed JSON from the ESP32
const id = msg.topic.split('/')[2];            // chinarsoft/demo/<id>/state
const STATES  = ['STOPPED', 'RUNNING', 'IDLE', 'FAULT'];
const REASONS = { 0: '-', 1: 'material shortage', 2: 'jam', 3: 'motor overload',
                  4: 'sensor fault', 9: 'guard open' };
// Your plant decides this table: which time is planned, which time costs OEE.
const BUCKET = { t_run: 'run', t_stop: 'planned', t_idle: 'unplanned', t_fault: 'unplanned' };

const mem = context.get(id) || { last: null, goodOff: 0, scrapOff: 0 };
const last = mem.last;
mem.last = p;
if (!last) { context.set(id, mem); node.status({ fill: 'grey', shape: 'dot', text: id + ': first message' }); return null; }

// counters only go up - unless the ESP32 rebooted. Then the new value IS the delta.
const delta = (now, before) => now >= before ? now - before : now;
if (p.good  < last.good)  mem.goodOff  += last.good;
if (p.scrap < last.scrap) mem.scrapOff += last.scrap;
context.set(id, mem);

const add = {};
for (const [key, bucket] of Object.entries(BUCKET)) {
    const dt = delta(p[key], last[key]);
    if (dt > 0) add[bucket] = (add[bucket] || 0) + dt;
}
const state = STATES[p.state] ?? 'UNKNOWN';
const now = state === 'RUNNING' ? 'run' : BUCKET['t_' + { STOPPED: 'stop', IDLE: 'idle', FAULT: 'fault' }[state]];
if (!Object.keys(add).length) add[now] = 0;   // still write a row: the state timeline needs every change

const reason = REASONS[p.reason] ?? String(p.reason);
const good = p.good + mem.goodOff, scrap = p.scrap + mem.scrapOff;
const ts = Date.now();
msg.payload = Object.entries(add).map(([bucket, dt]) =>
    `machine,line=esp32,device=${id},bucket=${bucket} ` +
    `state="${state}",reason="${reason}",good=${good}i,scrap=${scrap}i,` +
    `cycle=${p.cycle_s},temp=${p.temp_c},dt=${dt}i ${ts}`).join('\n');
node.status({ fill: state === 'RUNNING' ? 'green' : 'yellow', shape: 'dot',
              text: `${state} · good ${good} · scrap ${scrap}` });
return msg;

// POST line protocol to InfluxDB 3 Core (same as Factory Monitoring)
msg.method  = 'POST';
msg.url     = `${env.get('INFLUX_URL') || 'http://127.0.0.1:8181'}/api/v3/write_lp?db=factory&precision=ms`;
msg.headers = { 'Authorization': 'Bearer ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain' };
return msg;

// online / offline: the ESP32's last will, published by the broker when the device vanishes
const id = msg.topic.split('/')[2];
const on = msg.payload === 'online';
node.status({ fill: on ? 'green' : 'red', shape: on ? 'dot' : 'ring', text: `${id}: ${msg.payload}` });
return msg;
